  ('m_rich_10',        'milestone', 'Erreiche Platz 10 der Reichenliste',   'Die Top 10 der NEXA.',                                        'mission_growth',  'rich_rank',         'state',    '{"rank":10}',              1, 1, 1800, 1800, 1, 24, false, 100),
